class Linear_Output_Block(Block):
    def __init__(
        self, C=torch.empty((0, 0)), D=torch.empty((0, 0)), *args, **kwargs
    ) -> None:
        _C = to_tensor(C)
        _D = to_tensor(D)

        self.ny = _C.size(0) if _C.numel() else 0
        self.nx = _C.size(1) if _C.numel() else 0
        self.nu = _D.size(1) if _D.numel() else 0
        if self.ny == 0:
            self.ny = _D.size(0) if _D.numel() else 0

        super().__init__(nw=self.ny, nz=self.nx + self.nu, *args, **kwargs)

        self.register_buffer("C", _C)
        self.register_buffer("D", _D)

    def forward(self, z: Tensor):
        assert z.size(1) == self.nx + self.nu
        x = z[:, : self.nx, :]
        u = z[:, self.nx :, :]
        w = torch.matmul(self.C, x) + torch.matmul(self.D, u)  # type: ignore
        return w


class Discrete_Nonlinear_Function_Block(Block):
    def __init__(self, *args, **kwargs) -> None:
        super().__init__(*args, **kwargs)

    def init_norm(self, sys_data: System_data):
        raise NotImplementedError(
            "This function should determine normalization matrices Tw and Tiz for the given input data"
        )

    def forward(self, z: Tensor, mats=None):
        # CHANGED (D-195): optional per-pass constants, forwarded to `nonlinear_function` only
        # when supplied. Subclasses that take no `mats` never receive one, because the
        # Interconnect hands it to the single block that advertises `pass_mats`.
        assert z.size(1) == self.nx + self.nu
        w = self.nonlinear_function(z) if mats is None else self.nonlinear_function(z, mats)
        return w

    def nonlinear_function(self, z: Tensor):
        raise NotImplementedError(
            "This function should describe the discrete nonlinear function of the block"
        )

    def forward(self, x: Tensor, u: Tensor, obc_pass=None, pass_mats=None):
        # CHANGED (D-194/D-195): `obc_pass` is the once-per-objective `(mats, dmats)` pair,
        # passed as a TENSOR-TUPLE ARGUMENT so its graph contract under
        # torch.compile is explicit (an input, not a mutated attribute). None = no per-objective
        # coefficient: with a correction attached the module applies its synchronized frozen
        # coefficient (prediction, validation, diagnostics); without one this argument is inert and the
        # path is bit-identical to before it existed.
        # reshape state and input tensor dimensions for use in interconnect
        x_size = x.size()
        if len(x.size()) <= 2:
            x = x.view(x.size(0), self.nx, 1)
            state_has_correct_dimension = False
        else:
            state_has_correct_dimension = True

        u_size = u.size()
        if len(u.size()) <= 2:
            u = u.view(u.size(0), self.nu, 1)
            input_has_correct_dimension = False
        else:
            input_has_correct_dimension = True

        assert x.size(0) == u.size(0) # batch dimension is currently required
        self.nb = x.size(0)

        if not self.initialized_forward_function:
            self.init_forward()
            self.initialized_forward_function = True

        input_signals = [x, u]
        output_signals = []
        for ix in range(2, self.n_input_signals):
            input_signals.append(torch.zeros((self.nb, self.input_signal_sizes[ix], 1), device=x.device, dtype=x.dtype))
        for ix in range(0, self.n_output_signals):
            output_signals.append(torch.zeros((self.nb, self.output_signal_sizes[ix], 1), device=x.device, dtype=x.dtype))

        # CHANGED: propagate device/dtype so pipeline works on GPU and with float16/float32
        if self.array_connection_matrices[0][0].device != x.device or self.array_connection_matrices[0][0].dtype != x.dtype:
            for i in range(len(self.array_connection_matrices)):
                for j in range(len(self.array_connection_matrices[i])):
                    self.array_connection_matrices[i][j] = \
                        self.array_connection_matrices[i][j].to(device=x.device, dtype=x.dtype)

        for output_signal_ix in self.order_output_signal_computation:
            for input_signal_ix in self.output_ix_sorted_input_ix_dependencies[output_signal_ix]:
                output_signals[output_signal_ix] += torch.matmul(self.array_connection_matrices[output_signal_ix][input_signal_ix], input_signals[input_signal_ix])

            if output_signal_ix >= 2:
                # CHANGED (D-195): hand the per-pass matrix structure to the ONE block that
                # declared it wants it. `_pass_mats_ix` is an int fixed at wiring time and
                # `pass_mats` is an ARGUMENT, so the branch specialises away under torch.compile
                # instead of being decided from mutable state (the mistake D-194 records).
                _bi = output_signal_ix - 2
                if pass_mats is not None and _bi == self._pass_mats_ix:
                    input_signals[output_signal_ix] = self.connected_blocks[_bi].forward(
                        output_signals[output_signal_ix], pass_mats)
                else:
                    input_signals[output_signal_ix] = self.connected_blocks[_bi].forward(output_signals[output_signal_ix]) # offset by two for connected blocks since the progressed state and output are not registered as blocks

        y = output_signals[1]
        xp = output_signals[0]

        # CHANGED (D-192): one-step orthogonal-by-construction subtraction. The attached
        # correction returns `E_route J_b(vbar, x_b, u) theta` as (nb, nx, 1): a forward-mode JVP
        # of the physical block's transition in the coefficient direction on the routed physical
        # rows, exact zeros on the additional-state rows. Applied to the progressed state ONLY;
        # the output map `y` and `output_only()` are untouched. Nothing runs when no correction
        # is attached, which keeps every existing model bit-identical.
        _obc = getattr(self, 'obc_correction', None)
        if _obc is not None:
            xp = xp - _obc(x, u, obc_pass)

        # save input signals for referencing purpose
        if self.nb == 1 and self.save_signals == True:
            concat_input_signals = np.concatenate(input_signals, axis=1)[0,:,:]
            concat_output_signals = np.concatenate(output_signals, axis=1)[0,:,:]
            if self.first_step_eval:
                self.saved_input_signals = concat_input_signals
                self.saved_output_signals = concat_output_signals
                self.first_step_eval = False
            else:
                self.saved_input_signals = np.append(self.saved_input_signals, concat_input_signals, axis=1) # type: ignore
                self.saved_output_signals = np.append(self.saved_output_signals, concat_output_signals, axis=1) # type: ignore


        if not state_has_correct_dimension: xp = xp.view(self.nb, self.nx)
        if self.ny == 1: y = y.view(self.nb)
        if self.ny >= 2: y = y.view(self.nb, self.ny)

        assert x_size == xp.size()

        return y, xp

